import React, { useState, useEffect, useRef } from 'react';

function IntroOverlay({ onComplete }) {
  const [step, setStep] = useState(0);
  const [showMessage, setShowMessage] = useState(false);
  const audioRefs = useRef({
    car: new Audio('/assets/audio/car-driving.mp3'),
    crash: new Audio('/assets/audio/crash.mp3'),
    heartbeat: new Audio('/assets/audio/heartbeat.mp3'),
    flatline: new Audio('/assets/audio/flatline.mp3'),
    heartbeat2: new Audio('/assets/audio/heartbeat.mp3'),
    background: new Audio('/assets/audio/sorrow-music.mp3')
  });

  useEffect(() => {
    const sequence = async () => {
      // Car driving sound
      await audioRefs.current.car.play();
      await new Promise(resolve => setTimeout(resolve, 3000));

      // Crash sound
      audioRefs.current.car.pause();
      await audioRefs.current.crash.play();
      await new Promise(resolve => setTimeout(resolve, 2000));

      // Heartbeat
      await audioRefs.current.heartbeat.play();
      await new Promise(resolve => setTimeout(resolve, 3000));

      // Flatline
      audioRefs.current.heartbeat.pause();
      await audioRefs.current.flatline.play();
      await new Promise(resolve => setTimeout(resolve, 2000));

      // Second heartbeat
      await audioRefs.current.heartbeat2.play();
      await new Promise(resolve => setTimeout(resolve, 3000));

      // Show message
      setShowMessage(true);
      await new Promise(resolve => setTimeout(resolve, 4000));

      // Start background music
      audioRefs.current.background.loop = true;
      audioRefs.current.background.volume = 0.3;
      await audioRefs.current.background.play();

      // Complete intro
      onComplete();
    };

    sequence();

    return () => {
      // Cleanup audio on unmount
      Object.values(audioRefs.current).forEach(audio => {
        audio.pause();
        audio.currentTime = 0;
      });
    };
  }, [onComplete]);

  return (
    <div className="fixed inset-0 bg-black z-50 flex items-center justify-center">
      <div className={`text-center transition-opacity duration-1000 ${showMessage ? 'opacity-100' : 'opacity-0'}`}>
        <h2 className="text-4xl font-bold text-white mb-4">
          ชีวิตสั้นกว่าที่คิด...
        </h2>
        <p className="text-2xl text-gray-300">
          วางแผนวันสุดท้ายไว้ก่อนดีไหม?
        </p>
      </div>
    </div>
  );
}

export default IntroOverlay;
